// Convierte una fila de la tabla "policies" de Supabase (snake_case) al
// formato que usa el resto de la app (camelCase, con evidencia anidada).
function fromDbRow(row) {
  return {
    id: row.id,
    titulo: row.titulo,
    ciudad: row.ciudad,
    pais: row.pais || "",
    categoria: row.categoria,
    anio: row.anio || "",
    resumen: row.resumen || "",
    resultados: row.resultados || "",
    fuenteNombre: row.fuente_nombre || "",
    fuenteUrl: row.fuente_url || "",
    evidencia: { nivel: row.evidencia_nivel || "", nota: row.evidencia_nota || "" },
  };
}

// Convierte el formulario de "Agregar política" (camelCase) a una fila
// lista para insertar en Supabase (snake_case).
function toDbRow(form) {
  return {
    id: "user-" + Date.now(),
    titulo: form.titulo,
    ciudad: form.ciudad,
    pais: form.pais,
    categoria: form.categoria,
    anio: form.anio,
    resumen: form.resumen,
    resultados: form.resultados,
    fuente_nombre: form.fuenteNombre,
    fuente_url: form.fuenteUrl,
    evidencia_nivel: form.evidenciaNivel,
    evidencia_nota: form.evidenciaNota.trim(),
  };
}

