// Dimensiones del mapa vectorizado y proyección Mercator calibrada empíricamente
// contra las coordenadas reales de varios países del propio archivo (ver notas del chat).
const MAP_W = 1009.6727;
const MAP_H = 665.96301;
const PROJ = { xScale: 2.80593, xOffset: 474.856, yScale: -160.02698, yOffset: 462.84656 };
function projectLatLon(lat, lon) {
  const x = PROJ.xScale * lon + PROJ.xOffset;
  const merc = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI / 180) / 2));
  const y = PROJ.yScale * merc + PROJ.yOffset;
  return [x, y];
}

